={{ JSON.stringify({
 model: $('Config').first().json.anthropic_model,
 max_tokens: 1024, temperature: 0.2,
 system: $json.ai_system,
 messages: [{ role: 'user', content: $json.ai_user }],
 tools: [{ name: 'record_turn', description: 'Record the intent, the order details from the latest message, and the reply.', input_schema: $json.claude_schema }],
 tool_choice: { type: 'tool', name: 'record_turn' }
}) }}

={{ JSON.stringify({
 systemInstruction: { parts: [{ text: $json.ai_system }] },
 contents: [{ role: 'user', parts: [{ text: $json.ai_user }] }],
 generationConfig: { temperature: 0.2, responseMimeType: 'application/json', responseSchema: $json.ai_schema }
}) }}

parameters.jsCode:
// Read the answer from whichever AI was used (Gemini or Claude) into one shape
const ctx = $('Build Context').first().json;
const claude = $('AI Understand (Claude)').isExecuted;
const r = (claude ? $('AI Understand (Claude)') : $('AI Understand (Gemini)')).first().json;
let ai = null, ai_error = '';
try {
  if (r.error) throw new Error(typeof r.error === 'string' ? r.error : (r.error.message || JSON.stringify(r.error)));
  if (r.ai_system !== undefined)   // a deactivated node just passes its input through
    throw new Error(`the ${claude ? 'Claude' : 'Gemini'} AI step did not run. Check that it is not deactivated and that ai_provider in Config is "${claude ? 'anthropic' : 'gemini'}"`);
  if (claude) {
    const tool = (r.content ?? []).find(c => c.type === 'tool_use');
    if (tool) ai = tool.input;
    else {
      const t = (r.content ?? []).filter(c => c.type === 'text').map(c => c.text).join('').trim();
      if (!t) throw new Error('empty AI response');
      ai = JSON.parse(t.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
    }
  } else {
    const parts = r.candidates?.[0]?.content?.parts ?? [];
    const t = parts.filter(p => typeof p.text === 'string' && !p.thought).map(p => p.text).join('').trim();
    if (!t) throw new Error('empty AI response');
    ai = JSON.parse(t.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, ''));
  }
  if (!ai || typeof ai !== 'object') throw new Error('AI response is not an object');
} catch (e) { ai = null; ai_error = String(e.message || e).slice(0, 300); }
const lastAssistant = [...ctx.history].reverse().find(h => h.role === 'assistant');
// The Orders tab is only needed for orders and confirmations (saves a sheet read on questions)
const need_orders = Boolean(ai) && (ai.intent === 'order' || lastAssistant?.flag === 'summary');
return [{ json: { provider: claude ? 'anthropic' : 'gemini', ai, ai_error, need_orders } }];

// The rules decide: prices, dates, capacity, delivery areas and order confirmation are checked here, not by the AI.
const ctx = $('Build Context').first().json;
const cfg = $('Config').first().json;
const tz = cfg.timezone || 'Asia/Kolkata';
const today = DateTime.now().setZone(tz).startOf('day');
const owner = cfg.owner_name || 'the owner';
const call = cfg.owner_phone ? `, or call us on ${cfg.owner_phone}` : '';
const inr = n => '₹' + Number(n).toLocaleString('en-IN');
const fmtDate = d => d.toFormat('ccc d LLL');
const base = { channel: ctx.channel, session_id: ctx.session_id, tg_chat_id: ctx.tg_chat_id, text: ctx.text,
               history_text: ctx.history_text, customer_display_name: ctx.customer_display_name };
let draftOut = '';   // the order so far, saved with this reply so the next message can build on it
const done = (o) => [{ json: { ...base, action: 'none', intent: '', flag: '', summary_hash: '', order_json: draftOut, alert_type: '', alert_reason: '', ...o } }];

// 1. The AI's answer (already parsed)
const { ai, ai_error } = $('Parse AI').first().json;
const keepDraft = Object.keys(ctx.draft || {}).length ? JSON.stringify(ctx.draft) : '';
if (ai_error) {
  draftOut = keepDraft;
  return done({ reply: `Sorry, I'm having a little trouble right now. Please try again in a minute${call}.`, flag: 'ai-error',
                alert_type: ctx.history.some(h => h.flag === 'ai-error') ? '' : 'error', alert_reason: 'AI step failed: ' + ai_error });
}
const intent = String(ai.intent || 'other');

// 2. Helpers
const menu = ctx.menu, areas = ctx.areas;
const ordersRead = $('Read Orders').isExecuted ? $('Read Orders').all() : [];
const ordersOk = !ordersRead.some(i => i.json.error);
const orders = ordersOk ? ordersRead.map(i => i.json).filter(o => o.order_id) : [];
const normSize = s => {
  let x = String(s ?? '').toLowerCase().replace(/kilograms?|kilos?|kgs?/g, 'kg').replace(/grams?|gms?/g, 'g').replace(/\s+/g, '');
  if (/^(half|1\/2)kg$/.test(x) || x === 'halfakg') x = '0.5kg';
  const g = x.match(/^(\d+(?:\.\d+)?)g$/); if (g) x = (Number(g[1]) / 1000) + 'kg';
  return x.replace(/^\.5/, '0.5');
};
const normPhone = p => {
  let d = String(p ?? '').replace(/\D/g, '');
  if (d.length === 12 && d.startsWith('91')) d = d.slice(2);
  if (d.length === 11 && d.startsWith('0')) d = d.slice(1);
  return /^[6-9]\d{9}$/.test(d) ? d : null;
};
const findArea = a => {
  const s = String(a ?? '').trim().toLowerCase();
  if (!s) return null;
  return Object.keys(areas).find(k => s.includes(k.toLowerCase()) || k.toLowerCase().includes(s)) ?? null;
};
const hashOf = o => { const s = JSON.stringify(o); let h = 5381; for (let i = 0; i < s.length; i++) h = ((h * 33) ^ s.charCodeAt(i)) >>> 0; return h.toString(36); };
const list = arr => arr.length <= 1 ? arr.join('') : arr.slice(0, -1).join(', ') + ' and ' + arr[arr.length - 1];
const menuList = () => {
  const by = {};
  for (const m of menu.filter(m => m.available)) (by[m.item_name] ??= []).push(`${m.size} ${inr(m.price_inr)}`);
  return Object.entries(by).map(([n, s]) => `• ${n}: ${s.join(', ')}`).join('\n');
};

// 3. Check an order against the menu, dates, capacity and delivery areas
function evaluate(o) {
  const missing = [], problems = [];
  const n = {};
  const rows = o.item_id ? menu.filter(m => m.item_id === String(o.item_id).toUpperCase()) : [];
  let row = null;
  if (!o.item_id) missing.push('which cake you would like');
  else if (!rows.length) problems.push(`Sorry, that isn't on our menu. Here is what we make:\n${menuList()}`);
  else if (!rows.some(m => m.available)) problems.push(`Sorry, ${rows[0].item_name} isn't available right now${rows[0].notes ? ` (${rows[0].notes})` : ''}. Here is what we make:\n${menuList()}`);
  else {
    const sizes = rows.filter(m => m.available);
    if (!o.size && sizes.length === 1) row = sizes[0];   // only one size: no need to ask
    else if (!o.size) missing.push(`the size (${sizes.map(m => m.size).join(' or ')})`);
    else {
      row = sizes.find(m => normSize(m.size) === normSize(o.size)) ?? null;
      if (!row) problems.push(`${rows[0].item_name} comes in ${sizes.map(m => m.size).join(' or ')}.`);
    }
  }
  const qty = Number.isInteger(o.quantity) && o.quantity > 0 ? o.quantity : 1;
  if (qty > Number(cfg.max_cakes_per_order || 3)) problems.push(`For more than ${cfg.max_cakes_per_order || 3} cakes, ${owner} will plan it with you personally. Please share your phone number.`);
  if (row) {
    n.item_id = row.item_id; n.item_name = row.item_name; n.size = row.size;
    if (o.eggless === true && !row.eggless_available) problems.push(`${row.item_name} can't be made eggless.`);
    else if (o.eggless === null || o.eggless === undefined) { if (row.eggless_available) missing.push('with egg or eggless'); else n.eggless = false; }
    else n.eggless = Boolean(o.eggless);
  }
  n.quantity = qty;
  // date
  if (!o.delivery_date) missing.push('the date you need it');
  else {
    const d = DateTime.fromISO(String(o.delivery_date), { zone: tz }).startOf('day');
    const lead = row ? row.lead_time_days : 1;
    const earliest = today.plus({ days: lead });
    const closed = String(cfg.closed_dates || '').split(',').map(s => s.trim()).filter(Boolean);
    const booked = day => orders.filter(x => String(x.delivery_date) === day && !/cancel/i.test(String(x.status)))
                                .reduce((s, x) => s + (Number(x.quantity) || 1), 0);
    const cap = Number(cfg.daily_capacity || 6);
    const fits = day => !closed.includes(day.toISODate()) && booked(day.toISODate()) + qty <= cap;
    const nextFree = (from) => { const out = []; for (let i = 0; i < 30 && out.length < 3; i++) { const x = from.plus({ days: i }); if (fits(x)) out.push(fmtDate(x)); } return out; };
    if (!d.isValid) missing.push('the date you need it');
    else if (d < today) problems.push('That date has already passed. Which date would you like?');
    else if (d < earliest) problems.push(`${row ? row.item_name : 'Our cakes'} need${row ? 's' : ''} ${lead} day${lead > 1 ? 's' : ''}' notice, so the earliest is ${fmtDate(earliest)}. Same-day orders aren't possible.`);
    else if (d > today.plus({ days: Number(cfg.max_advance_days || 30) })) problems.push(`We take orders up to ${cfg.max_advance_days || 30} days ahead. Please message us closer to the date.`);
    else if (closed.includes(d.toISODate())) problems.push(`We're closed on ${fmtDate(d)}. Available: ${list(nextFree(earliest))}.`);
    else if (!ordersOk) problems.push(`I can't check availability for ${fmtDate(d)} right now. ${owner} will confirm it with you.`);
    else if (!fits(d)) problems.push(`Sorry, we're fully booked on ${fmtDate(d)}. Available: ${list(nextFree(d.plus({ days: 1 })))}.`);
    else n.delivery_date = d.toISODate();
  }
  n.delivery_time = String(o.delivery_time ?? '').slice(0, 40);
  // pickup or delivery
  const f = String(o.fulfilment ?? '').toLowerCase();
  if (f !== 'pickup' && f !== 'delivery') missing.push('pickup or delivery');
  else if (f === 'pickup') { n.fulfilment = 'pickup'; n.area = ''; }
  else if (!Object.keys(areas).length) problems.push('Sorry, we only offer pickup at the moment.');
  else if (!o.area) missing.push('your delivery area');
  else {
    const a = findArea(o.area);
    if (!a) problems.push(`Sorry, we don't deliver to ${String(o.area).slice(0, 40)}. We deliver to ${list(Object.keys(areas))}, or you can pick up.`);
    else { n.fulfilment = 'delivery'; n.area = a; }
  }
  // message on cake
  const msg = String(o.message_on_cake ?? '').trim();
  if (msg.length > Number(cfg.max_cake_message_chars || 30)) problems.push(`The message on the cake can be up to ${cfg.max_cake_message_chars || 30} characters.`);
  n.message_on_cake = msg;
  n.special_requests = String(o.special_requests ?? '').trim().slice(0, 150);
  // contact
  const name = String(o.customer_name ?? '').trim() || ctx.customer_display_name;
  if (!name) missing.push('your name'); else n.customer_name = name.slice(0, 60);
  if (!o.phone) missing.push('your phone number');
  else { const p = normPhone(o.phone); if (!p) problems.push('Please send a 10-digit Indian mobile number.'); else n.phone = p; }
  // price
  let pricing = null;
  if (row && !missing.length && !problems.length) {
    const unit = row.price_inr + (n.eggless ? row.eggless_extra_inr : 0);
    const cake = unit * qty;
    const fee = n.fulfilment === 'delivery' ? areas[n.area] : 0;
    const total = cake + fee;
    pricing = { cake_price_inr: cake, delivery_fee_inr: fee, total_inr: total,
                advance_inr: Math.round(total * Number(cfg.advance_payment_pct || 50) / 100) };
  }
  return { missing, problems, n, pricing, item_problem: Boolean(o.item_id) && !row && problems.length > 0 && !rows.some(m => m.available) || (Boolean(o.item_id) && !rows.length) };
}

const summaryText = (n, p) => [
  `Here's your order:`,
  `• ${n.quantity} × ${n.item_name}, ${n.size}${n.eggless ? ', eggless' : ''}`,
  n.message_on_cake ? `• Message on cake: "${n.message_on_cake}"` : null,
  n.special_requests ? `• Special request: ${n.special_requests} (${owner} will confirm this and any extra cost)` : null,
  n.fulfilment === 'delivery' ? `• Delivery to ${n.area} on ${fmtDate(DateTime.fromISO(n.delivery_date, { zone: tz }))}${n.delivery_time ? ` (${n.delivery_time})` : ''}`
                              : `• Pickup on ${fmtDate(DateTime.fromISO(n.delivery_date, { zone: tz }))}${n.delivery_time ? ` (${n.delivery_time})` : ''}`,
  `• Name: ${n.customer_name}, phone ${n.phone}`,
  `Cake ${inr(p.cake_price_inr)}${p.delivery_fee_inr ? ` + delivery ${inr(p.delivery_fee_inr)}` : ''} = total ${inr(p.total_inr)}`,
  `Shall I send this order request? Reply YES to confirm, or tell me what to change.`,
].filter(Boolean).join('\n');

const lastAssistant = [...ctx.history].reverse().find(h => h.role === 'assistant');
// Merge: the order so far, updated with whatever the latest message gave
const fresh = ai.order && typeof ai.order === 'object' ? ai.order : {};
const prevDraft = ctx.draft || {};
const order = ai.start_over   // a different order: keep only who the customer is
  ? Object.fromEntries(['customer_name', 'phone'].filter(k => prevDraft[k]).map(k => [k, prevDraft[k]]))
  : { ...prevDraft };
for (const [k, v] of Object.entries(fresh)) if (v !== null && v !== undefined && v !== '') order[k] = v;
draftOut = Object.keys(order).length ? JSON.stringify(order) : '';
const shortYes = /^\s*(y|ye|yes+|yes please|yeah|yep|yup|confirm|confirmed|ok|okay|ok go ahead|go ahead|haan|ha|hya|ji|done|sure)\s*[.!]*\s*$/i.test(ctx.text);

// 4. Confirmation of the summary shown in the previous message
if (lastAssistant?.flag === 'summary' && lastAssistant.order_json && (shortYes || ai.customer_confirmed === true)) {
  let shown = null; try { shown = JSON.parse(lastAssistant.order_json); } catch (e) {}
  const current = evaluate(order);
  const changed = !shortYes && current.pricing && hashOf(current.n) !== lastAssistant.summary_hash;
  if (shown && !changed) {
    const ev = evaluate(shown);                       // re-check: the date may have filled up meanwhile
    if (ev.pricing && hashOf(ev.n) === lastAssistant.summary_hash) {
      const h = lastAssistant.summary_hash;
      const dup = orders.find(o => o.session_id === ctx.session_id && o.order_hash === h);
      if (dup) return done({ intent, reply: `Your order request ${dup.order_id} is already with us. ${owner} will be in touch soon.` });
      const id = 'ORD-' + DateTime.now().setZone(tz).toFormat('yyMMdd') + '-' + Math.random().toString(36).slice(2, 6).toUpperCase();
      const pct = Number(cfg.advance_payment_pct || 50);
      return done({
        intent, action: 'log_order', flag: 'order-logged', alert_type: 'order', summary_hash: h, order_json: '',
        order: { order_id: id, ...ev.n, ...ev.pricing, order_hash: h },
        reply: `Thank you, ${ev.n.customer_name}! Your order request ${id} has been sent to ${owner}. ` +
               `${owner} will confirm it and share UPI details for the ${pct}% advance (${inr(ev.pricing.advance_inr)}) ${cfg.owner_reply_hours ? `between ${cfg.owner_reply_hours}` : 'soon'}. ` +
               `Your order is booked once the advance is paid.`,
      });
    }
    const why = [...ev.problems, ...ev.missing.map(m => 'Missing: ' + m)].join('\n');
    return done({ intent, flag: 'order-in-progress', reply: `Sorry, something changed before I could send it:\n${why}` });
  }
}

// 5. Hand-offs to the owner
const phone = normPhone(order.phone);
const prev = ctx.history.map(h => h.flag);
const askedPhone = lastAssistant?.flag === 'handoff';
if (['custom_request', 'complaint', 'human_requested'].includes(intent) || (askedPhone && phone && intent !== 'order')) {
  const reason = { custom_request: 'custom cake request', complaint: 'complaint', human_requested: 'customer asked for a person' }[intent] || 'phone number for an earlier request';
  if (!phone) {
    return done({ intent, flag: 'handoff', alert_type: prev.some(f => f.startsWith('handoff')) ? '' : 'handoff', alert_reason: reason,
      reply: intent === 'custom_request'
        ? `Custom designs are handled by ${owner} personally, who will share ideas and a price. What's the best phone number to reach you on?`
        : `I'll pass this to ${owner} right away. What's the best phone number to reach you on?` });
  }
  return done({ intent, flag: 'handoff+phone', alert_type: prev.includes('handoff+phone') ? '' : 'handoff', alert_reason: reason, order: { phone },
    reply: `Thank you! ${owner} will call or WhatsApp you on ${phone}${cfg.owner_reply_hours ? ` (usually between ${cfg.owner_reply_hours})` : ''}.` });
}

// 6. Orders in progress
if (intent === 'order') {
  const ev = evaluate(order);
  if (ev.pricing) {
    const h = hashOf(ev.n);
    const sent = orders.find(o => o.session_id === ctx.session_id && o.order_hash === h);
    if (sent) return done({ intent, reply: `Your order request ${sent.order_id} is already with ${owner}. Would you like anything else?` });
    return done({ intent, flag: 'summary', summary_hash: h, order_json: JSON.stringify(ev.n), reply: summaryText(ev.n, ev.pricing) });
  }
  const parts = [];
  if (ev.item_problem) return done({ intent, flag: 'order-in-progress', reply: ev.problems[0] + '\nWhich one would you like?' });
  if (ev.problems.length) parts.push(ev.problems.join('\n'));
  if (ev.missing.length) parts.push(`${ev.problems.length ? 'Also, could you tell me' : 'Lovely! To prepare your order, could you tell me'} ${list(ev.missing)}?`);
  return done({ intent, flag: 'order-in-progress', reply: parts.join('\n\n') });
}

// 7. Questions, greetings, anything else: the AI's reply, with a price check
let reply = String(ai.reply || '').trim().slice(0, 700) || `I'm not sure about that. I'll check with ${owner}.`;
const allowed = new Set([0, ...menu.flatMap(m => [m.price_inr, m.eggless_extra_inr]), ...Object.values(areas)]);
const amounts = [...reply.matchAll(/(?:₹|rs\.?|inr)\s*([0-9][0-9,]*(?:\.[0-9]+)?)|([0-9][0-9,]*(?:\.[0-9]+)?)\s*(?:rupees|\/-)/gi)]
  .map(m => Number(String(m[1] || m[2]).replace(/,/g, '')));
let flag = '';
if (amounts.some(x => !allowed.has(x))) {
  reply = `Here are our current prices:\n${menuList()}\nDelivery: ${Object.entries(areas).map(([k, v]) => `${k} ${inr(v)}`).join(', ') || 'pickup only'}.`;
  flag = 'price-guard';
}
return done({ intent, flag, reply });

// No AI call: message limits, or the Menu sheet could not be read
const ctx = $input.first().json;
const cfg = $('Config').first().json;
const call = cfg.owner_phone ? `, or call us on ${cfg.owner_phone}` : '';
const sheetProblem = !ctx.limit_reply && ctx.sheet_error;
return [{ json: {
  ...ctx,
  reply: ctx.limit_reply || `Sorry, I can't look up our menu right now. Please try again in a few minutes${call}.`,
  action: 'none', intent: '', flag: sheetProblem ? 'sheet-error' : 'limit',
  summary_hash: '', order_json: Object.keys(ctx.draft || {}).length ? JSON.stringify(ctx.draft) : '',
  alert_type: sheetProblem && !ctx.history.some(h => h.flag === 'sheet-error') ? 'error' : '',
  alert_reason: sheetProblem ? ctx.sheet_error : '',
} }];

// Exactly the columns of the Orders tab
const d = $input.first().json, o = d.order;
return [{ json: {
  order_id: o.order_id, created_at: DateTime.now().setZone($('Config').first().json.timezone || 'Asia/Kolkata').toISO(),
  status: 'pending-confirmation', channel: d.channel, session_id: d.session_id,
  customer_name: o.customer_name, phone: o.phone, item_id: o.item_id, item_name: o.item_name, size: o.size,
  eggless: o.eggless ? 'yes' : 'no', quantity: o.quantity, message_on_cake: o.message_on_cake, special_requests: o.special_requests || '',
  delivery_date: o.delivery_date, delivery_time: o.delivery_time, fulfilment: o.fulfilment, area: o.area,
  cake_price_inr: o.cake_price_inr, delivery_fee_inr: o.delivery_fee_inr, total_inr: o.total_inr, advance_inr: o.advance_inr,
  order_hash: o.order_hash,
} }];

// Final reply and owner alert. An order is only reported as sent if it was saved to the sheet.
const cfg = $('Config').first().json;
const d = $('Decide Reply').isExecuted ? $('Decide Reply').first().json : $('Fallback Reply').first().json;
const out = { ...d };
if (d.action === 'log_order') {
  const res = $('Log Order').isExecuted ? $('Log Order').first().json : { error: 'not run' };
  if (res.error) {
    out.flag = 'order-save-failed';
    out.alert_type = 'order-save-failed';
    out.alert_reason = 'The order could not be saved to the sheet: ' + String(res.error.message || res.error).slice(0, 200);
    out.reply = `Sorry, I couldn't send your order just now. ${cfg.owner_name} has been alerted and will contact you on ${d.order.phone}.`;
  }
}
const o = d.order || {};
const subjects = {
  order: `New order request ${o.order_id}: ${o.item_name} ${o.size} for ${o.delivery_date}`,
  'order-save-failed': `ACTION NEEDED: order not saved (${o.customer_name}, ${o.phone})`,
  handoff: `Customer needs you: ${d.alert_reason}`,
  error: `Order assistant problem: ${d.alert_reason}`,
};
const orderLines = o.order_id || out.alert_type === 'order-save-failed' ? [
  `Order: ${o.order_id}`, `Customer: ${o.customer_name}, ${o.phone}`,
  `Cake: ${o.quantity} x ${o.item_name}, ${o.size}${o.eggless ? ', eggless' : ''}`,
  `Message on cake: ${o.message_on_cake || '-'}`,
  `Special request: ${o.special_requests || '-'}`,
  `${o.fulfilment === 'delivery' ? 'Delivery to ' + o.area : 'Pickup'} on ${o.delivery_date} ${o.delivery_time || ''}`,
  `Cake ₹${o.cake_price_inr} + delivery ₹${o.delivery_fee_inr} = total ₹${o.total_inr}; advance ₹${o.advance_inr}`,
  ``, `Next: call or WhatsApp the customer, confirm, and send UPI details for the advance. Then set the status in the Orders tab.`,
] : [];
out.alert_subject = subjects[out.alert_type] || '';
out.alert_body = [
  ...(out.alert_type === 'handoff' ? [`Reason: ${d.alert_reason}`, `Phone: ${o.phone || 'not given yet'}`] : []),
  ...(out.alert_type === 'error' ? [`Problem: ${d.alert_reason}`] : []),
  ...orderLines,
  ``, `Channel: ${d.channel} (session ${d.session_id})`,
  ``, `Recent conversation:`, (d.history_text || '').slice(-3000), `Customer: ${d.text}`, `Assistant: ${out.reply}`,
  ``, `Order sheet: ${cfg.sheet_url}`,
].join('\n');
return [{ json: out }];

// Two rows for the Chat Log tab: the customer's message and the assistant's reply
const d = $('Finalize Reply').first().json;
const now = DateTime.now().setZone($('Config').first().json.timezone || 'Asia/Kolkata');
const row = (ts, role, message, extra = {}) => ({ timestamp: ts, session_id: d.session_id, channel: d.channel, role,
  message, intent: '', flag: '', summary_hash: '', order_json: '', ...extra });
return [
  { json: row(now.toISO(), 'customer', d.text) },
  { json: row(now.plus({ milliseconds: 1 }).toISO(), 'assistant', d.reply,
              { intent: d.intent || '', flag: d.flag || '', summary_hash: d.summary_hash || '', order_json: d.order_json || '' }) },
];
